// Add mode to AppState
const AppState = {
  currentMode: 'stock', // 'stock' or 'preorder'
  cart: JSON.parse(localStorage.getItem('puerto_hype_cart') || '[]').map(item => ({ ...item, cartItemId: item.cartItemId || Date.now().toString() + Math.random().toString() })),
  currentFilter: 'all',
  searchQuery: '',
  whatsappNumber: '5212294135613'
};

// Inicialización cuando el DOM está listo

// --- AUTO-CATEGORIZATION & SIZES FOR PREORDER ---
const streetwearBrands = ['Hellstar', 'Godspeed', 'Gallery Dept', 'Essentials', 'Stussy', 'Bape', 'Boss', 'Sp5der', 'Acne Studios', 'Off White', 'Duaa', 'Majestik', 'Life Hustle', 'Supply', 'Rough Play', 'Harmony', 'Saint', 'Casa Blanca', 'Balenciaga', 'Galazgod', 'Nike', 'Adidas', 'Mixed Emotion', 'Valley', 'Alo', 'Van'];
const jeansBrands = ['Purple Brand', 'Denim Tears', 'Amiri', 'First Row', 'BKYS'];
const sandalBrands = ['Crocs']; 
const backpackBrands = ['Sprayground'];
const jewelryBrands = ['Van Cleef', 'Chrome Hearts'];
const sneakerBrands = ['HOKA', 'ON CLOUD'];

PREORDER_PRODUCTS.forEach(p => {
  const nameLow = p.name.toLowerCase();
  if (backpackBrands.includes(p.brand)) {
    p.category = 'mochilas';
    p.customizable = false;
    p.sizes = [];
  } else if (sandalBrands.includes(p.brand) || nameLow.includes('slide') || nameLow.includes('foam rnnr') || nameLow.includes('sandal')) {
    p.category = 'chanclas';
    p.sizes = ['24', '25', '26', '27', '28', '29'];
    p.customizable = true;
  } else if (jewelryBrands.includes(p.brand) || nameLow.includes('van cleef') || p.brand.toLowerCase().includes('van cleef')) {
    p.category = 'pulseras';
    p.customizable = false;
    p.sizes = [];
  } else if (jeansBrands.includes(p.brand)) {
    p.category = 'jeans';
    p.sizes = ['28', '30', '32', '34', '36'];
    p.customizable = true;
  } else if (streetwearBrands.includes(p.brand)) {
    p.category = 'playeras';
    p.sizes = ['S', 'M', 'L', 'XL'];
    p.customizable = true;
  } else if (p.brand === 'Gorras') {
    p.customizable = false;
  } else if (sneakerBrands.includes(p.brand)) {
    p.category = 'sneakers';
    p.sizes = ['22', '23', '24', '25', '26', '27', '28', '29', '30'];
    p.customizable = false;
  } else {
    p.category = 'playeras';
    p.sizes = ['S', 'M', 'L', 'XL'];
    p.customizable = true;
  }
});
// ------------------------------------------------


async function initApp() {
  try {
    let res = await fetch(`data/stock_products.json?t=${Date.now()}`);
    if (!res.ok) {
      res = await fetch(`https://raw.githubusercontent.com/tuttisports13-sys/puerto_hype/main/data/stock_products.json?t=${Date.now()}`);
    }
    if (res.ok) {
      STOCK_PRODUCTS = await res.json();
    }
  } catch (e) {
    try {
      const res = await fetch(`https://raw.githubusercontent.com/tuttisports13-sys/puerto_hype/main/data/stock_products.json?t=${Date.now()}`);
      if (res.ok) STOCK_PRODUCTS = await res.json();
    } catch(err) {
      console.error('Error fetching stock products:', err);
    }
  }
  // Productos ocultos desde el panel de admin no se muestran en la tienda
  STOCK_PRODUCTS = (STOCK_PRODUCTS || []).filter(p => !p.hidden);
  setupEventListeners();
  const btnStock = document.getElementById('btn-stock');
  if (btnStock) {
    btnStock.click();
  } else {
    renderProducts();
  }
  updateCartUI();
  if (typeof window.updateUserUI === 'function') {
    window.updateUserUI();
  }
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initApp);
} else {
  initApp();
}

// Renderizar la cuadrícula de productos con filtrado
function renderProducts() {
  const container = document.getElementById('products-grid');
  if (!container) return;

let currentProducts = STOCK_PRODUCTS;
if (AppState.currentMode === 'preorder') currentProducts = PREORDER_PRODUCTS;
if (AppState.currentMode === 'preorder-sports') currentProducts = SPORTS_PRODUCTS;


  // Grupos del catálogo en stock: los productos del admin vienen todos como "sneakers",
  // así que se separan por nombre/talla para que Jerseys, Calzado y Outlet muestren lo correcto.
  const stockGroup = (prod) => {
    if (prod.category === 'mayoreo' || String(prod.id).startsWith('lote-')) return 'mayoreo';
    if (/local|visita|jersey|portugal 20/i.test(prod.name)) return 'jerseys';
    const shoeSize = (prod.sizes || []).some(sz => { const n = parseFloat(sz); return (/^\d{2}(\.5)?\s*(cm)?$/i.test(String(sz).trim()) && n >= 21 && n <= 32) || /^\d{1,2}(\.5)?\s*(mx|us)$/i.test(String(sz).trim()); });
    if (shoeSize) return 'calzado';
    return 'outlet';
  };

  const filtered = currentProducts.filter(prod => {
    const isSearching = AppState.searchQuery.trim().length > 0;
    // Si NO está buscando y estamos en deportes, ocultar productos individuales en la vista principal 'all'
    if (AppState.currentMode === 'preorder-sports' && !isSearching && AppState.currentFilter === 'all' && !prod.isFolder && !prod.category?.endsWith('_folder')) return false;
    
    // Si ESTÁ buscando, ignoramos el filtro de categoría para buscar en TODO el catálogo
    const matchesCategory = isSearching || AppState.currentFilter === 'all' || 
                            prod.category === AppState.currentFilter || 
                            prod.brand === AppState.currentFilter ||
                            (AppState.currentFilter === 'mayoreo' && (prod.category === 'mayoreo' || prod.id.startsWith('lote-'))) ||
                            (['jerseys', 'calzado', 'outlet'].includes(AppState.currentFilter) && AppState.currentMode !== 'preorder' && AppState.currentMode !== 'preorder-sports' && stockGroup(prod) === AppState.currentFilter);
                            
    // Validar nombre
    const matchesSearch = prod.name.toLowerCase().includes(AppState.searchQuery.toLowerCase());
    
    return matchesCategory && matchesSearch;
  });


  if (filtered.length === 0) {
    container.innerHTML = `
      <div style="grid-column: 1 / -1; text-align: center; padding: 40px 10px; color: var(--text-muted);">
        <p style="font-size: 1.1rem; font-weight: 800; font-family: var(--font-display); color: #fff; margin-bottom: 6px;">
          No se encontraron productos
        </p>
        <p style="font-size: 0.8rem;">Intenta con otra palabra clave o selecciona otra categoría.</p>
      </div>
    `;
    return;
  }

  container.innerHTML = filtered.map(product => {
    // "NUEVO" solo en productos subidos en los últimos 14 días (el id del admin lleva la fecha: stock-<ms>)
    const addedAt = parseInt(String(product.id).replace(/^stock-/, ''), 10);
    const isRecent = addedAt > 1e12 && Date.now() - addedAt < 14 * 24 * 60 * 60 * 1000;
    const badgeText = product.soldOut ? 'AGOTADO' : product.badge === 'NUEVO' ? (isRecent ? 'NUEVO' : '') : (product.badge || 'Lotes limitados');

    // Animación de cambio de imagen al pasar el ratón (Estilo Gucci)
    let hoverImgSrc = null;
    if (Array.isArray(product.gallery) && product.gallery.length > 1) {
      hoverImgSrc = product.gallery.find(img => img && img !== product.image) || product.gallery[1];
    } else if (product.hoverImage && product.hoverImage !== product.image) {
      hoverImgSrc = product.hoverImage;
    }

    return `
    <article class="product-card" data-id="${product.id}">
      <div class="product-thumb" onclick="openQuickView('${product.id}')" style="cursor: pointer;">
        ${badgeText ? `<span class="product-badge ${product.badgeType || ''}">${badgeText}</span>` : ''}
        <img 
          class="product-img" 
          src="${product.image}" 
          alt="${product.name}" 
          loading="lazy" 
          onerror="this.onerror=null;this.src='/images/sin-foto.svg'"
        />
        ${hoverImgSrc ? `
        <img 
          class="product-img-hover" 
          src="${hoverImgSrc}" 
          alt="${product.name}" 
          loading="lazy" 
          onerror="this.style.display='none'"
        />` : ''}
      </div>
      <div class="product-body">
        <h3 class="product-name">${product.name}</h3>
        <div class="product-sizes" style="font-size: 0.74rem; color: var(--text-muted); margin-bottom: 6px;">
          ${product.sizes && product.sizes.length > 0 ? 'Tallas: ' + product.sizes.join(', ') : ''}
          ${product.password ? '<span style="color:var(--text-primary); font-weight:700; display:block; margin-top:3px;">' + product.password + '</span>' : ''}
        </div>
        ${product.description ? `
        <div class="product-description" style="font-size: 0.76rem; color: #4b5563; margin-bottom: 8px; line-height: 1.35; background: #f9fafb; padding: 6px 8px; border-radius: 6px; border-left: 2.5px solid #000000;">
          ${product.description}
        </div>
        ` : ''}

${product.isFolder || product.section === 'preorder' || (product.section === 'preorder-sports' && product.link) ? '' : `
<div class="product-pricing">
  <span class="price-wholesale">${product.hasVersionSelector ? '$600 - $650 MXN' : '$' + product.price + ' MXN'}</span>
</div>
`}

<div class="product-actions">
  ${product.isFolder ? `
    <button class="btn-add-cart" onclick="openSportsFolder('${product.targetFilter}')" style="display: flex; justify-content: center; align-items: center; gap: 8px; width: 100%;"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="width: 18px; height: 18px;"><path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z"></path></svg> VER CATÁLOGO</button>
  ` : product.section === 'preorder-sports' && product.link ? `
    <a href="${product.link}" target="_blank" class="btn-add-cart" style="text-decoration: none; display: flex; justify-content: center; align-items: center; gap: 8px; width: 100%; box-sizing: border-box;">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="width: 18px; height: 18px;"><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"></path><polyline points="15 3 21 3 21 9"></polyline><line x1="10" y1="14" x2="21" y2="3"></line></svg>
      VER CATÁLOGO
    </a>
  ` : product.soldOut ? `
    <button class="btn-add-cart" disabled style="opacity: 0.45; cursor: not-allowed;">AGOTADO</button>
  ` : `
    <button class="btn-add-cart" onclick="${product.customizable ? `openQuickView('${product.id}')` : `addToCart('${product.id}')`}">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
        <circle cx="9" cy="21" r="1"></circle>
        <circle cx="20" cy="21" r="1"></circle>
        <path d="M1 1h4l2.68 13.39a2 2 0 0 0 2 1.61h9.72a2 2 0 0 0 2-1.61L23 6H6"></path>
      </svg>
      AGREGAR AL CARRITO
    </button>
  `}
</div>

      </div>
    </article>
  `;}).join('');
}

