// Control del Carrito (Abrir / Cerrar)
function toggleCart(isOpen) {
  const overlay = document.getElementById('cart-overlay');
  const drawer = document.getElementById('cart-drawer');
  if (isOpen) {
    overlay.classList.add('open');
    drawer.classList.add('open');
    document.body.style.overflow = 'hidden';
  } else {
    overlay.classList.remove('open');
    drawer.classList.remove('open');
    document.body.style.overflow = '';
  }
}

// Agregar producto al carrito
// Agregar producto al carrito
function addToCart(productId, customization = null, customPriceAdd = 0, selectedSize = null) {
  const product = STOCK_PRODUCTS.find(p => p.id === productId) || PREORDER_PRODUCTS.find(p => p.id === productId) || SPORTS_PRODUCTS.find(p => p.id === productId);

  if (!product || product.soldOut) return;

  let base = product.hasVersionSelector ? currentQvVersionBasePrice : product.price;
  let finalName = product.name;
  if (product.hasVersionSelector && currentQvSelectedVersion) {
    finalName += ` (Versión ${currentQvSelectedVersion})`;
  }

  const existing = AppState.cart.find(item => item.id === productId && item.name === finalName && JSON.stringify(item.customization) === JSON.stringify(customization));
  if (existing) {
    existing.quantity += 1;
  } else {
    AppState.cart.push({
      cartItemId: Date.now().toString() + Math.random().toString(),
      id: product.id,
      name: finalName,
      price: base,
      retailPrice: product.retailPrice,
      image: product.image,
      size: selectedSize || (product.sizes ? (product.sizes[0] || 'Unitalla') : 'Unitalla'),
      quantity: 1,
      customization: customization,
      customPriceAdd: customPriceAdd,
      finalPrice: base + customPriceAdd
    });
  }

  saveCart();
  updateCartUI();
  showToast(`¡${product.name} agregado al carrito!`);
  toggleCart(true); // Abre el carrito automáticamente
}

// Modificar cantidad
function updateQuantity(cartItemId, delta) {
  const item = AppState.cart.find(i => i.cartItemId === cartItemId);
  if (!item) return;

  item.quantity += delta;
  if (item.quantity <= 0) {
    removeFromCart(cartItemId);
  } else {
    saveCart();
    updateCartUI();
  }
}

// Eliminar producto
function removeFromCart(cartItemId) {
  AppState.cart = AppState.cart.filter(item => item.cartItemId !== cartItemId);
  saveCart();
  updateCartUI();
}

// Guardar en LocalStorage
function saveCart() {
  localStorage.setItem('puerto_hype_cart', JSON.stringify(AppState.cart));
}

// Calcular totales y escala de descuentos
function calculateWholesaleSummary() {
  const totalPieces = AppState.cart.reduce((sum, item) => sum + item.quantity, 0);
  
  // Exclude 'po-' items from the numeric sum because they are "POR COTIZAR"
  const subtotal = AppState.cart.reduce((sum, item) => {
    if (item.id.startsWith('po-')) return sum; // Cotizar = $0 en el cálculo automático
    return sum + ((item.finalPrice || item.price) * item.quantity);
  }, 0);

  const hasPreorderItems = AppState.cart.some(item => item.id.startsWith('po-'));

  let extraDiscountPercent = 0;
  let tierLabel = 'Precio Mayoreo';

  const discountAmount = Math.round(subtotal * (extraDiscountPercent / 100));
  const total = subtotal - discountAmount;

  return {
    totalPieces,
    subtotal,
    extraDiscountPercent,
    discountAmount,
    total,
    tierLabel,
    hasPreorderItems,
    isWholesaleQualified: totalPieces >= 5
  };
}

// Actualizar la interfaz del carrito y contadores
function updateCartUI() {
  const summary = calculateWholesaleSummary();
  
  // Actualizar badges de contador
  const badges = document.querySelectorAll('.cart-count-badge');
  badges.forEach(b => {
    b.textContent = summary.totalPieces;
    b.style.display = summary.totalPieces > 0 ? 'flex' : 'none';
  });

  // Barra de progreso de mínimo de 5 piezas
  const progressFill = document.getElementById('wholesale-progress-fill');
  const progressText = document.getElementById('wholesale-progress-text');
  if (progressFill && progressText) {
    const percent = Math.min(100, Math.round((summary.totalPieces / 5) * 100));
    progressFill.style.width = `${percent}%`;

    if (summary.totalPieces === 0) {
      progressText.innerHTML = `Llevas <strong>0 / 5 piezas</strong> para activar precio mayoreo`;
    } else if (summary.totalPieces < 5) {
      const faltan = 5 - summary.totalPieces;
      progressText.innerHTML = `Te faltan <span style="color: var(--neon-lime);">${faltan} pieza${faltan > 1 ? 's' : ''}</span> para precio mayoreo`;
    } else {
      progressText.innerHTML = `<span style="color: var(--neon-mint);">¡PRECIO MAYOREO ACTIVADO! 🎉 (${summary.totalPieces} pzas)</span>`;
    }
  }

  // Lista de items en Drawer
  const itemsContainer = document.getElementById('cart-items-container');
  if (itemsContainer) {
    if (AppState.cart.length === 0) {
      itemsContainer.innerHTML = `
        <div class="cart-empty">
          <svg style="width: 48px; height: 48px; opacity: 0.4;" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5">
            <circle cx="9" cy="21" r="1"></circle>
            <circle cx="20" cy="21" r="1"></circle>
            <path d="M1 1h4l2.68 13.39a2 2 0 0 0 2 1.61h9.72a2 2 0 0 0 2-1.61L23 6H6"></path>
          </svg>
          <p style="font-family: var(--font-display); font-weight: 800; color: #fff;">Tu carrito está vacío</p>
          <p style="font-size: 0.75rem;">Agrega al menos 5 prendas o calzado para iniciar tu pedido mayorista.</p>
        </div>
      `;
    } else {
      itemsContainer.innerHTML = AppState.cart.map(item => `
        <div class="cart-item">
          <img src="${item.image}" alt="${item.name}" class="cart-item-thumb">
          <div class="cart-item-info">
            <div>
              <h4 class="cart-item-name">${item.name}</h4>
              <div style="font-size: 0.68rem; color: var(--text-muted); margin-top: 2px;">Talla: ${item.size}</div>
            </div>
            <div style="display: flex; align-items: center; justify-content: space-between; margin-top: 6px;">
              <span class="cart-item-price">${item.id.startsWith('po-') ? '<span style="color:var(--neon-lime)">Cotizar</span>' : '$' + (item.price * item.quantity) + ' MXN'}</span>
              <div class="cart-item-qty">
                <button class="qty-btn" onclick="updateQuantity('${item.cartItemId}', -1)">-</button>
                <span class="qty-val">${item.quantity}</span>
                <button class="qty-btn" onclick="updateQuantity('${item.cartItemId}', 1)">+</button>
                <button class="btn-remove-item" onclick="removeFromCart('${item.cartItemId}')" title="Eliminar">✕</button>
              </div>
            </div>
          </div>
        </div>
      `).join('');
    }
  }

  // Totales en Drawer
  const subtotalEl = document.getElementById('cart-subtotal');
  const discountRow = document.getElementById('cart-discount-row');
  const discountEl = document.getElementById('cart-discount-amount');
  const totalEl = document.getElementById('cart-total');
  const checkoutBtn = document.getElementById('btn-whatsapp-checkout');

  if (subtotalEl) subtotalEl.textContent = `$${summary.subtotal.toLocaleString()} MXN`;
  if (totalEl) totalEl.textContent = `$${summary.total.toLocaleString()} MXN`;

  if (discountRow && discountEl) {
    if (summary.extraDiscountPercent > 0) {
      discountRow.style.display = 'flex';
      discountEl.textContent = `-${summary.extraDiscountPercent}% ($${summary.discountAmount.toLocaleString()} MXN)`;
    } else {
      discountRow.style.display = 'none';
    }
  }

  if (checkoutBtn) {
    if (summary.totalPieces === 0) {
      checkoutBtn.disabled = true;
      checkoutBtn.style.opacity = '0.5';
      checkoutBtn.style.pointerEvents = 'none';
    } else {
      checkoutBtn.disabled = false;
      checkoutBtn.style.opacity = '1';
      checkoutBtn.style.pointerEvents = 'auto';
    }
  }
}

// Generar pedido por WhatsApp
function sendOrderViaWhatsApp() {
  const summary = calculateWholesaleSummary();
  if (AppState.cart.length === 0) return;

  const currentUser = window.UserManager ? window.UserManager.getCurrentUser() : null;

  // Registrar pedido en el historial de compras del usuario
  let registeredOrder = null;
  if (window.UserManager && typeof window.UserManager.saveOrder === 'function') {
    registeredOrder = window.UserManager.saveOrder({
      items: AppState.cart,
      totalPieces: summary.totalPieces,
      subtotal: summary.subtotal,
      total: summary.total,
      hasPreorderItems: summary.hasPreorderItems
    });
  }

  const orderFolio = registeredOrder ? registeredOrder.folio : ('#PH-' + Math.floor(10000 + Math.random() * 90000));

  let message = `🔥 *NUEVO PEDIDO - PUERTO HYPE* 🔥\n`;
  message += `━━━━━━━━━━━━━━━━━━━━━\n`;
  message += `🔖 *FOLIO DE PEDIDO:* ${orderFolio}\n`;
  if (currentUser) {
    message += `👤 *CLIENTE REGISTRADO:* @${currentUser.username} (${currentUser.email})\n`;
  }
  message += `━━━━━━━━━━━━━━━━━━━━━\n`;
  message += `Hola! Quiero cotizar y apartar las siguientes piezas:\n\n`;

  AppState.cart.forEach((item, index) => {
    const itemPrice = item.id.startsWith("po-") ? "Por cotizar" : ("$" + (item.price * item.quantity) + " MXN"); const finalItemPrice = item.id.startsWith("po-") ? "Por cotizar" : ("$" + ((item.finalPrice || item.price) * item.quantity) + " MXN");
    message += `• *${item.quantity}x* ${item.name} ${item.sizes && item.sizes.length > 0 ? '(' + item.sizes[0] + ')' : ''} — *${finalItemPrice}*\n`;
    if (item.customization) { message += `  > Personalizado: ${item.customization.name || ''} ${item.customization.patches ? '| Parches: ' + item.customization.patches : ''}\n`; }
  });

  let totalTextWA = `$${summary.total.toLocaleString()} MXN`;
  if (summary.hasPreorderItems && summary.total === 0) {
    totalTextWA = 'POR COTIZAR';
  } else if (summary.hasPreorderItems && summary.total > 0) {
    totalTextWA = `$${summary.total.toLocaleString()} MXN + Artículos por Cotizar`;
  }

  message += `\n━━━━━━━━━━━━━━━━━━━━━\n`;
  message += `📦 *Total de piezas:* ${summary.totalPieces} pzas\n`;
  message += `💰 *Subtotal:* ${totalTextWA}\n`;
  if (summary.extraDiscountPercent > 0) {
    message += `🏷️ *Descuento por volumen (-${summary.extraDiscountPercent}%):* -$${summary.discountAmount.toLocaleString()} MXN\n`;
  }
  message += `💳 *TOTAL FINAL ESTIMADO:* ${totalTextWA}\n\n`;
  
  
  message += `¿Tienen disponibilidad en estas tallas para pago y envío hoy mismo? Gracias!`;

  const url = `https://wa.me/${AppState.whatsappNumber}?text=${encodeURIComponent(message)}`;
  window.open(url, '_blank');

  // Notificar al usuario y limpiar carrito
  if (currentUser) {
    showToast(`¡Pedido ${orderFolio} guardado en tu historial!`);
  } else {
    showToast(`¡Pedido ${orderFolio} generado!`);
  }
  AppState.cart = [];
  saveCart();
  updateCartUI();
  const cartDrawer = document.getElementById('cart-drawer');
  const cartOverlay = document.getElementById('cart-overlay');
  if (cartDrawer) cartDrawer.classList.remove('open');
  if (cartOverlay) cartOverlay.classList.remove('open');
}

// Mostrar Toast
function showToast(text) {
  let container = document.getElementById('toast-container');
  if (!container) {
    container = document.createElement('div');
    container.id = 'toast-container';
    container.className = 'toast-container';
    document.body.appendChild(container);
  }

  const toast = document.createElement('div');
  toast.className = 'toast';
  toast.innerHTML = `
    <span style="color: var(--neon-lime);">✔</span>
    <span>${text}</span>
  `;
  container.appendChild(toast);

  setTimeout(() => {
    toast.style.opacity = '0';
    toast.style.transform = 'translateY(-10px)';
    toast.style.transition = 'all 0.3s ease';
    setTimeout(() => toast.remove(), 300);
  }, 2200);
}

// Quick View Modal Logic
let currentGallery = [];
let currentGalleryIndex = 0;

var currentQvProductId = null;
var currentQvVersionBasePrice = 0;
var currentQvSelectedVersion = "";

function selectQvVersion(btn, basePrice) {
  document.querySelectorAll('.version-btn').forEach(b => {
    b.classList.remove('active');
    b.style.background = 'transparent';
    b.style.color = 'white';
    b.style.borderColor = 'var(--border-color)';
  });
  btn.classList.add('active');
  btn.style.background = 'var(--neon-lime)';
  btn.style.color = '#000';
  btn.style.borderColor = 'var(--neon-lime)';
  
  currentQvVersionBasePrice = basePrice;
  currentQvSelectedVersion = btn.getAttribute('data-version') === 'jugador' ? 'Jugador' : 'Fan';
  
  updateQvPriceDisplay();
}

function updateQvPriceDisplay() {
  if (!currentQvProductId) return;
  const product = STOCK_PRODUCTS.find(p => p.id === currentQvProductId) || PREORDER_PRODUCTS.find(p => p.id === currentQvProductId) || SPORTS_PRODUCTS.find(p => p.id === currentQvProductId);
  if (!product) return;
  
  let base = product.hasVersionSelector ? currentQvVersionBasePrice : product.price;
  
  let extra = 0;
  if (document.getElementById('qv-check-name') && document.getElementById('qv-check-name').checked) extra += 50;
  if (document.getElementById('qv-check-patch') && document.getElementById('qv-check-patch').checked) {
    extra += (30 * parseInt(document.getElementById('qv-patch-select').value));
  }
  
  document.getElementById('qv-price').textContent = `$${base + extra} MXN`;
}

function toggleNameInput() {
  if(typeof updateQvPriceDisplay === 'function') updateQvPriceDisplay();
  const isChecked = document.getElementById('qv-check-name').checked;
  document.getElementById('qv-name-input-container').style.display = isChecked ? 'block' : 'none';
}

function togglePatchInput() {
  if(typeof updateQvPriceDisplay === 'function') updateQvPriceDisplay();
  const isChecked = document.getElementById('qv-check-patch').checked;
  document.getElementById('qv-patch-input-container').style.display = isChecked ? 'block' : 'none';
}

function addToCartFromModal() {
  if (!currentQvProductId) return;
  
  const hasName = document.getElementById('qv-check-name').checked;
  const nameText = document.getElementById('qv-name-input').value;
  const hasPatch = document.getElementById('qv-check-patch').checked;
  const patchCount = document.getElementById('qv-patch-select').value;
  
  let customization = null;
  let customPriceAdd = 0;
  
  if (hasName && nameText.trim() !== '') {
    customization = customization || {};
    customization.name = nameText.trim();
    customPriceAdd += 50;
  }
  
  if (hasPatch) {
    customization = customization || {};
    customization.patches = parseInt(patchCount);
    customPriceAdd += (30 * customization.patches);
  }
  
  let selectedSize = 'Unitalla';
const activeSizeBtn = document.querySelector('.qv-size-btn.active');
if (activeSizeBtn) {
  selectedSize = activeSizeBtn.dataset.size;
}

addToCart(currentQvProductId, customization, customPriceAdd, selectedSize);
  closeQuickView();
}

function openQuickView(productId) {
  const product = STOCK_PRODUCTS.find(p => p.id === productId) || PREORDER_PRODUCTS.find(p => p.id === productId) || SPORTS_PRODUCTS.find(p => p.id === productId);
  if (!product) return;
  
  currentQvProductId = productId;
  
  const modal = document.getElementById('quickview-modal');
  const title = document.getElementById('qv-title');
  const price = document.getElementById('qv-price');
  const img = document.getElementById('qv-main-img');
  const thumbContainer = document.getElementById('qv-thumbnails');
  
  title.textContent = product.name;
  
  const descEl = document.getElementById('qv-description');
  if (descEl) {
    if (product.description) {
      descEl.textContent = product.description;
      descEl.style.display = 'block';
    } else {
      descEl.style.display = 'none';
    }
  }
  
  // Render Sizes
  const sizeContainer = document.getElementById('qv-sizes');
  if (sizeContainer && product.sizes && product.sizes.length > 0) {
    sizeContainer.innerHTML = product.sizes.map((s, i) => `
      <button class="qv-size-btn ${i === 0 ? 'active' : ''}" data-size="${s}" onclick="selectQvSize(this)" style="padding: 8px 12px; border: 1.5px solid ${i === 0 ? '#000000' : 'var(--border-subtle)'}; background: ${i === 0 ? '#000000' : '#ffffff'}; color: ${i === 0 ? '#ffffff' : '#000000'}; font-weight: 800; border-radius: 6px; cursor: pointer; font-size: 0.85rem;">
        ${s}
      </button>
    `).join('');
    document.getElementById('qv-size-container').style.display = 'block';
  } else if (sizeContainer) {
    document.getElementById('qv-size-container').style.display = 'none';
  }

  // Reset version selector
const versionContainer = document.getElementById('qv-version-container');
if (versionContainer) {
  if (product.hasVersionSelector) {
    versionContainer.style.display = 'block';
    const fanBtn = document.querySelector('.version-btn[data-version="fan"]');
    if (fanBtn) selectQvVersion(fanBtn, 600);
  } else {
    versionContainer.style.display = 'none';
    currentQvVersionBasePrice = product.price;
    currentQvSelectedVersion = "";
  }
}

  // Handle Customization UI
  const qvCustomization = document.getElementById('qv-customization');
  if (qvCustomization) {
    if (product.customizable && product.category !== 'nba' && product.category !== 'balones' && product.category !== 'f1' && product.category !== 'sudaderas' && product.category !== 'conjunto-entrenamiento' && product.section !== 'preorder') {
      qvCustomization.style.display = 'block';
      document.getElementById('qv-check-name').checked = false;
      document.getElementById('qv-check-patch').checked = false;
      document.getElementById('qv-name-input').value = '';
      document.getElementById('qv-patch-select').value = '1';
      toggleNameInput();
      togglePatchInput();
    } else {
      qvCustomization.style.display = 'none';
    }
  }

  // Ensure "AGREGAR AL CARRITO" button is always visible even if not customizable
  // Wait, the button is INSIDE the qv-customization div in index.html!
  // If it's inside, setting qvCustomization to display:none hides the button too!
  // Let me move the button outside of qvCustomization inside this script.
  // Actually, I can just do it in JS: if not customizable, we still need a button to add to cart!
  
  price.textContent = product.section === 'preorder' ? 'Por cotizar' : `$${product.price} MXN`;
  
  currentGallery = product.gallery && product.gallery.length > 0 ? product.gallery : [product.image];
  currentGalleryIndex = 0;
  
  img.src = currentGallery[0];
  
  if (currentGallery.length > 1) {
    thumbContainer.innerHTML = currentGallery.map((src, i) => `
      <img src="${src}" class="qv-thumb ${i===0?'active':''}" onclick="setQVImage(${i})">
    `).join('');
    thumbContainer.style.display = 'flex';
  } else {
    thumbContainer.style.display = 'none';
  }
  
  modal.classList.add('open');
  document.body.style.overflow = 'hidden';
}

function setQVImage(index) {
  currentGalleryIndex = index;
  document.getElementById('qv-main-img').src = currentGallery[index];
  document.querySelectorAll('.qv-thumb').forEach((el, i) => {
    el.classList.toggle('active', i === index);
  });
}

function selectQvSize(btn) {
  document.querySelectorAll('.qv-size-btn').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  
  // Make active button a solid green box
  btn.style.backgroundColor = '#000000';
  btn.style.borderColor = '#000000';
  btn.style.color = '#ffffff';
  btn.style.fontWeight = '800';
  
  // reset others visually
  document.querySelectorAll('.qv-size-btn:not(.active)').forEach(b => {
    b.style.backgroundColor = '#ffffff';
    b.style.borderColor = 'var(--border-subtle)';
    b.style.color = '#000000';
    b.style.fontWeight = 'normal';
  });
}

function closeQuickView() {
  const modal = document.getElementById('quickview-modal');
  if (modal) modal.classList.remove('open');
  const lb = document.getElementById('lightbox-modal');
  if (!lb || !lb.classList.contains('open')) {
    document.body.style.overflow = '';
  }
}

// --- AI Chatbot Logic ---
document.addEventListener('DOMContentLoaded', () => {
  const chatToggle = document.getElementById('ai-chat-toggle');
  const chatWindow = document.getElementById('ai-chat-window');
  const chatClose = document.getElementById('ai-chat-close');
  const chatMessages = document.getElementById('ai-chat-messages');
  const chatInput = document.getElementById('ai-chat-input');
  const chatSend = document.getElementById('ai-chat-send');

  if (!chatToggle) return;

  let chatHistory = [];

  // Toggle chat
  chatToggle.addEventListener('click', () => {
    chatWindow.classList.remove('hidden');
    chatInput.focus();
  });

  chatClose.addEventListener('click', () => {
    chatWindow.classList.add('hidden');
  });

  // Handle send message
  const sendMessage = async () => {
    const text = chatInput.value.trim();
    if (!text) return;

    // Add user message to UI
    appendMessage('user', text);
    chatInput.value = '';

    // Show typing indicator
    const typingId = showTyping();

    try {
      const response = await fetch('/api/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ message: text, history: chatHistory })
      });

      removeTyping(typingId);

      if (!response.ok) {
        throw new Error('Error en el servidor');
      }

      const data = await response.json();
      appendMessage('bot', data.reply);
      
      // Update history
      chatHistory.push({ role: 'user', content: text });
      chatHistory.push({ role: 'bot', content: data.reply });

    } catch (error) {
      removeTyping(typingId);
      appendMessage('bot', 'Ups, hermano. Tuve una pequeña desconexión con mi servidor cerebral. ¿Me puedes volver a enviar tu pregunta? Si el problema persiste, mándanos WhatsApp directo: [📲 Escribir a WhatsApp](https://wa.me/5212294135613)');
      console.error(error);
    }
  };

  chatSend.addEventListener('click', sendMessage);
  chatInput.addEventListener('keypress', (e) => {
    if (e.key === 'Enter') sendMessage();
  });

  function appendMessage(role, text) {
    const msgDiv = document.createElement('div');
    msgDiv.className = `chat-msg ${role}`;
    // Linkify urls in text safely, or just set innerText
    // We will just use textContent to avoid XSS, but parse newlines
    const bubble = document.createElement('div');
    bubble.className = 'msg-bubble';
    
    // Quick and dirty markdown-like bold parsing
    let htmlText = text.replace(/</g, '&lt;').replace(/>/g, '&gt;');
    htmlText = htmlText.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');
    // Markdown link parsing
    // Solo links https (evita links peligrosos si alguien manipula la respuesta)
    htmlText = htmlText.replace(/\[([^\]]*?)\]\((https:\/\/[^\s"'()<>]+)\)/g, '<a href="$2" target="_blank" rel="noopener" style="color:var(--neon-lime); text-decoration:underline; font-weight:bold;">$1</a>');
    htmlText = htmlText.replace(/\n/g, '<br>');
    
    bubble.innerHTML = htmlText;
    msgDiv.appendChild(bubble);
    chatMessages.appendChild(msgDiv);
    chatMessages.scrollTop = chatMessages.scrollHeight;
  }

  function showTyping() {
    const id = 'typing-' + Date.now();
    const msgDiv = document.createElement('div');
    msgDiv.className = 'chat-msg bot';
    msgDiv.id = id;
    msgDiv.innerHTML = `
      <div class="msg-bubble" style="padding: 12px 14px;">
        <div class="typing-indicator">
          <span></span><span></span><span></span>
        </div>
      </div>
    `;
    chatMessages.appendChild(msgDiv);
    chatMessages.scrollTop = chatMessages.scrollHeight;
    return id;
  }

  function removeTyping(id) {
    const el = document.getElementById(id);
    if (el) el.remove();
  }
});

// --- CONTROLADOR INTERACTIVO DE LIGHTBOX & ZOOM ---
let lbCurrentGallery = [];
let lbCurrentIndex = 0;
let lbZoom = 1.0;
let lbPanX = 0;
let lbPanY = 0;
let lbIsDragging = false;
let lbStartX = 0;
let lbStartY = 0;
let lbInitialDistance = null;
let lbInitialZoom = 1.0;
let lbHintTimeout = null;

function openLightbox(srcOrIndex) {
  const modal = document.getElementById('lightbox-modal');
  const img = document.getElementById('lightbox-img');
  if (!modal || !img) return;

  // Sincronizar galería con el producto actualmente abierto o la imagen proporcionada
  if (typeof currentGallery !== 'undefined' && currentGallery && currentGallery.length > 0) {
    lbCurrentGallery = currentGallery;
  } else if (srcOrIndex && typeof srcOrIndex === 'string') {
    lbCurrentGallery = [srcOrIndex];
  } else {
    lbCurrentGallery = [];
  }

  if (typeof srcOrIndex === 'number') {
    lbCurrentIndex = Math.max(0, Math.min(srcOrIndex, lbCurrentGallery.length - 1));
  } else if (typeof srcOrIndex === 'string') {
    const idx = lbCurrentGallery.indexOf(srcOrIndex);
    lbCurrentIndex = idx >= 0 ? idx : 0;
    if (idx === -1 && srcOrIndex) {
      lbCurrentGallery = [srcOrIndex];
      lbCurrentIndex = 0;
    }
  } else {
    lbCurrentIndex = 0;
  }

  // Cargar imagen y restablecer zoom/posición
  resetLightboxZoom();
  updateLightboxImage();
  renderLightboxThumbs();

  modal.classList.add('open');
  document.body.style.overflow = 'hidden';

  // Mostrar hint temporal
  const hint = document.getElementById('lightbox-hint');
  if (hint) {
    hint.style.opacity = '1';
    clearTimeout(lbHintTimeout);
    lbHintTimeout = setTimeout(() => {
      hint.style.opacity = '0';
    }, 3200);
  }
}

function updateLightboxImage() {
  const img = document.getElementById('lightbox-img');
  const counter = document.getElementById('lightbox-counter');
  const prevBtn = document.getElementById('lb-prev-btn');
  const nextBtn = document.getElementById('lb-next-btn');

  if (lbCurrentGallery.length > 0 && lbCurrentGallery[lbCurrentIndex]) {
    if (img) img.src = lbCurrentGallery[lbCurrentIndex];
  }

  if (counter) {
    counter.textContent = `${lbCurrentIndex + 1} / ${Math.max(1, lbCurrentGallery.length)}`;
  }

  // Mostrar u ocultar flechas si hay una sola foto
  if (prevBtn) prevBtn.style.display = lbCurrentGallery.length > 1 ? 'flex' : 'none';
  if (nextBtn) nextBtn.style.display = lbCurrentGallery.length > 1 ? 'flex' : 'none';

  // Actualizar miniatura activa
  document.querySelectorAll('.lb-thumb').forEach((th, i) => {
    th.classList.toggle('active', i === lbCurrentIndex);
  });
}

function renderLightboxThumbs() {
  const thumbsContainer = document.getElementById('lightbox-thumbs');
  if (!thumbsContainer) return;

  if (lbCurrentGallery.length <= 1) {
    thumbsContainer.style.display = 'none';
    return;
  }

  thumbsContainer.style.display = 'flex';
  thumbsContainer.innerHTML = lbCurrentGallery.map((src, idx) => `
    <img src="${src}" class="lb-thumb ${idx === lbCurrentIndex ? 'active' : ''}" onclick="setLightboxIndex(${idx}, event)" alt="Thumb ${idx + 1}">
  `).join('');
}

function setLightboxIndex(idx, event) {
  if (event) event.stopPropagation();
  lbCurrentIndex = idx;
  resetLightboxZoom();
  updateLightboxImage();
}

function lightboxPrev(event) {
  if (event) event.stopPropagation();
  if (lbCurrentGallery.length <= 1) return;
  lbCurrentIndex = (lbCurrentIndex - 1 + lbCurrentGallery.length) % lbCurrentGallery.length;
  resetLightboxZoom();
  updateLightboxImage();
}

function lightboxNext(event) {
  if (event) event.stopPropagation();
  if (lbCurrentGallery.length <= 1) return;
  lbCurrentIndex = (lbCurrentIndex + 1) % lbCurrentGallery.length;
  resetLightboxZoom();
  updateLightboxImage();
}

function applyLightboxTransform() {
  const img = document.getElementById('lightbox-img');
  const stage = document.getElementById('lightbox-stage');
  if (!img) return;

  if (lbZoom <= 1.05) {
    lbZoom = 1.0;
    lbPanX = 0;
    lbPanY = 0;
    if (stage) {
      stage.classList.remove('zoomed');
      stage.classList.remove('dragging');
    }
  } else {
    if (stage) stage.classList.add('zoomed');
  }

  img.style.transform = `translate(${lbPanX}px, ${lbPanY}px) scale(${lbZoom})`;
}

function zoomLightbox(delta) {
  const newZoom = Math.min(4.0, Math.max(1.0, lbZoom + delta));
  if (newZoom === 1.0) {
    resetLightboxZoom();
  } else {
    lbZoom = newZoom;
    applyLightboxTransform();
  }
}

function resetLightboxZoom() {
  lbZoom = 1.0;
  lbPanX = 0;
  lbPanY = 0;
  lbIsDragging = false;
  applyLightboxTransform();
}

function toggleLightboxZoom(event) {
  if (event) event.stopPropagation();
  if (lbZoom > 1.2) {
    resetLightboxZoom();
  } else {
    lbZoom = 2.4;
    // Si se hizo doble click/tap en una coordenada específica, centrar suavemente hacia allí
    if (event && event.clientX && event.clientY) {
      const stage = document.getElementById('lightbox-stage');
      if (stage) {
        const rect = stage.getBoundingClientRect();
        const offsetX = (event.clientX - (rect.left + rect.width / 2));
        const offsetY = (event.clientY - (rect.top + rect.height / 2));
        lbPanX = -offsetX * 0.8;
        lbPanY = -offsetY * 0.8;
      }
    }
    applyLightboxTransform();
  }
}

function closeLightbox() {
  const modal = document.getElementById('lightbox-modal');
  if (modal) {
    modal.classList.remove('open');
    resetLightboxZoom();
  }
  // Restaurar overflow solo si quickview tampoco está abierto
  const qv = document.getElementById('quickview-modal');
  if (!qv || !qv.classList.contains('open')) {
    document.body.style.overflow = '';
  }
}

function handleLightboxBackdropClick(event) {
  // Cerrar solo si hizo click directamente en el backdrop o stage sin estar en zoom
  if (event.target.id === 'lightbox-modal' || (event.target.id === 'lightbox-stage' && lbZoom <= 1.05)) {
    closeLightbox();
  }
}

// Configurar listeners de arrastre (Pan), zoom con rueda y gestos táctiles
document.addEventListener('DOMContentLoaded', () => {
  // Asegurar que el body nunca inicie con overflow bloqueado
  document.body.style.overflow = '';

  const stage = document.getElementById('lightbox-stage');
  if (!stage) return;

  // Zoom con la rueda del ratón (solo cuando el lightbox está abierto)
  stage.addEventListener('wheel', (e) => {
    const modal = document.getElementById('lightbox-modal');
    if (!modal || !modal.classList.contains('open')) return;
    e.preventDefault();
    const delta = e.deltaY < 0 ? 0.35 : -0.35;
    zoomLightbox(delta);
  }, { passive: false });

  // Arrastre con Mouse
  stage.addEventListener('mousedown', (e) => {
    const modal = document.getElementById('lightbox-modal');
    if (!modal || !modal.classList.contains('open')) return;
    if (lbZoom <= 1.05) return;
    lbIsDragging = true;
    lbStartX = e.clientX - lbPanX;
    lbStartY = e.clientY - lbPanY;
    stage.classList.add('dragging');
  });

  window.addEventListener('mousemove', (e) => {
    if (!lbIsDragging) return;
    e.preventDefault();
    lbPanX = e.clientX - lbStartX;
    lbPanY = e.clientY - lbStartY;
    applyLightboxTransform();
  });

  window.addEventListener('mouseup', () => {
    if (lbIsDragging) {
      lbIsDragging = false;
      const stageEl = document.getElementById('lightbox-stage');
      if (stageEl) stageEl.classList.remove('dragging');
    }
  });

  // Gestos Táctiles (Touch: Pan + Pinch to Zoom + Double Tap)
  let lastTouchTime = 0;

  stage.addEventListener('touchstart', (e) => {
    const modal = document.getElementById('lightbox-modal');
    if (!modal || !modal.classList.contains('open')) return;

    if (e.touches.length === 2) {
      // Pinch to Zoom
      e.preventDefault();
      lbInitialDistance = Math.hypot(
        e.touches[0].clientX - e.touches[1].clientX,
        e.touches[0].clientY - e.touches[1].clientY
      );
      lbInitialZoom = lbZoom;
    } else if (e.touches.length === 1) {
      const now = Date.now();
      if (now - lastTouchTime < 300) {
        // Double tap detectado
        e.preventDefault();
        toggleLightboxZoom(e.touches[0]);
        lastTouchTime = 0;
        return;
      }
      lastTouchTime = now;

      if (lbZoom > 1.05) {
        lbIsDragging = true;
        lbStartX = e.touches[0].clientX - lbPanX;
        lbStartY = e.touches[0].clientY - lbPanY;
        stage.classList.add('dragging');
      }
    }
  }, { passive: false });

  stage.addEventListener('touchmove', (e) => {
    const modal = document.getElementById('lightbox-modal');
    if (!modal || !modal.classList.contains('open')) return;

    if (e.touches.length === 2 && lbInitialDistance !== null) {
      e.preventDefault();
      const currentDistance = Math.hypot(
        e.touches[0].clientX - e.touches[1].clientX,
        e.touches[0].clientY - e.touches[1].clientY
      );
      const scaleDelta = currentDistance / lbInitialDistance;
      lbZoom = Math.min(4.0, Math.max(1.0, lbInitialZoom * scaleDelta));
      applyLightboxTransform();
    } else if (e.touches.length === 1 && lbIsDragging && lbZoom > 1.05) {
      e.preventDefault();
      lbPanX = e.touches[0].clientX - lbStartX;
      lbPanY = e.touches[0].clientY - lbStartY;
      applyLightboxTransform();
    }
  }, { passive: false });

  stage.addEventListener('touchend', (e) => {
    const modal = document.getElementById('lightbox-modal');
    if (!modal || !modal.classList.contains('open')) return;

    if (e.touches.length < 2) {
      lbInitialDistance = null;
    }
    if (e.touches.length === 0) {
      lbIsDragging = false;
      stage.classList.remove('dragging');
    }
  });

  // Atajos de teclado (Esc, Flechas)
  window.addEventListener('keydown', (e) => {
    const modal = document.getElementById('lightbox-modal');
    if (!modal || !modal.classList.contains('open')) return;

    if (e.key === 'Escape') {
      closeLightbox();
    } else if (e.key === 'ArrowLeft') {
      lightboxPrev();
    } else if (e.key === 'ArrowRight') {
      lightboxNext();
    }
  });
});


// --- SISTEMA DE RESEÑAS NATIVO ---
let currentReviewStars = 5;

function initReviews() {
  const stars = document.querySelectorAll('#review-stars .star');
  stars.forEach(star => {
    star.addEventListener('click', (e) => {
      currentReviewStars = parseInt(e.target.getAttribute('data-val'));
      stars.forEach(s => {
        if (parseInt(s.getAttribute('data-val')) <= currentReviewStars) {
          s.style.color = '#ffd700'; // filled
        } else {
          s.style.color = '#555'; // empty
        }
      });
    });
  });
  
  loadReviews();
}

async function loadReviews() {
  const container = document.getElementById('reviews-container');
  if (!container) return;
  
  try {
    const res = await fetch('/api/get-reviews');
    if (!res.ok) throw new Error('Error al cargar reseñas');
    const reviews = await res.json();
    
    if (reviews.length === 0) {
      container.innerHTML = '<p style="color: var(--text-muted); text-align: center; width: 100%;">Sé el primero en dejar una reseña.</p>';
      return;
    }
    
    // Duplicate reviews to create a seamless infinite scrolling marquee
    let repeatedReviews = [...reviews];
    while(repeatedReviews.length < 12) { repeatedReviews = [...repeatedReviews, ...reviews]; }
    repeatedReviews = [...repeatedReviews, ...repeatedReviews]; // Ensure it doubles the full set for perfect seamless loop
    
    const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (m) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[m]));
    container.innerHTML = repeatedReviews.map(r => {
      const stars = Math.max(0, Math.min(5, Number(r.stars) || 0));
      const img = /^https:\/\//.test(String(r.image || '')) ? r.image : '';
      return `
      <div class="review-card" style="background: var(--bg-card); padding: 20px; border-radius: var(--radius-md); border: 1px solid var(--border-subtle); display: flex; flex-direction: column;">
        <div style="display: flex; gap: 15px; align-items: center; margin-bottom: 12px;">
          <div style="width: 46px; height: 46px; background: #000; border-radius: 50%; display: flex; align-items: center; justify-content: center; color: #fff; font-weight: 800; font-size: 1.1rem; flex-shrink: 0;">
            ${esc(String(r.name || '?').charAt(0).toUpperCase())}
          </div>
          <div style="min-width: 0;">
            <h4 style="margin: 0; color: var(--text-primary); font-size: 0.95rem;">${esc(r.name)}</h4>
            <div style="color: #f59e0b; font-size: 0.8rem; margin-top: 3px;">${'★'.repeat(stars)}${'☆'.repeat(5 - stars)}</div>
          </div>
          <div style="margin-left: auto; color: var(--text-muted); font-size: 0.72rem; flex-shrink: 0;">${esc(r.date)}</div>
        </div>
        ${r.verified ? `<div><span class="rv-verified">✓ Compra verificada${r.product ? ` · <b>${esc(r.product)}</b>` : ''}</span></div>` : ''}
        <p style="color: var(--text-secondary); font-size: 0.9rem; line-height: 1.5; flex: 1; margin-top: 10px;">"${esc(r.text)}"</p>
        ${img ? `<img src="${esc(img)}" alt="Foto de ${esc(r.name)}" loading="lazy" onclick="openLightbox(this.src)" style="margin-top: 12px; width: 100%; max-height: 150px; object-fit: cover; border-radius: 8px; cursor: pointer; border: 1px solid var(--border-subtle);">` : ''}
      </div>`;
    }).join('');
  } catch (error) {
    console.error(error);
    container.innerHTML = '<p style="color: #ff6b6b; text-align: center; width: 100%;">Error al cargar las reseñas.</p>';
  }
}

function openReviewModal() {
  const modal = document.getElementById('review-modal');
  if (!modal) return;
  modal.classList.add('open');
}

function closeReviewModal() {
  const modal = document.getElementById('review-modal');
  if (modal) modal.classList.remove('open');
}

async function compressImage(file, maxWidth = 800, maxHeight = 800, quality = 0.7) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = event => {
      const img = new Image();
      img.src = event.target.result;
      img.onload = () => {
        let width = img.width;
        let height = img.height;
        
        if (width > maxWidth || height > maxHeight) {
          if (width > height) {
            height = Math.round((height *= maxWidth / width));
            width = maxWidth;
          } else {
            width = Math.round((width *= maxHeight / height));
            height = maxHeight;
          }
        }
        
        const canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        ctx.drawImage(img, 0, 0, width, height);
        
        // Use jpeg to ensure it's small, fallback if unsupported but jpeg is safe
        const compressedBase64 = canvas.toDataURL('image/jpeg', quality);
        resolve(compressedBase64);
      };
      img.onerror = error => reject(error);
    };
    reader.onerror = error => reject(error);
  });
}

async function submitReview() {
  const name = document.getElementById('review-name').value.trim();
  const text = document.getElementById('review-text').value.trim();
  const fileInput = document.getElementById('review-image');
  const btn = document.getElementById('btn-submit-review');
  
  if (!name || !text) {
    showToast('Por favor, ingresa tu nombre y opinión.');
    return;
  }
  
  btn.disabled = true;
  btn.textContent = 'PUBLICANDO...';
  
  try {
    let imageBase64 = "";
    if (fileInput.files && fileInput.files[0]) {
      const file = fileInput.files[0];
      
      // Remove 5MB check to allow client-side compression to handle large files
      imageBase64 = await compressImage(file, 800, 800, 0.7);
    }
    
    const res = await fetch('/api/submit-review', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name, stars: currentReviewStars, text, imageBase64, website: document.getElementById('review-website').value })
    });
    const result = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(result.error || 'Error en el servidor');
    
    showToast('¡Gracias! Tu reseña se publicará en cuanto la revisemos.');
    closeReviewModal();
    
    // Clear form
    document.getElementById('review-name').value = '';
    document.getElementById('review-text').value = '';
    fileInput.value = '';
    currentReviewStars = 5;
    
    
  } catch(e) {
    console.error(e);
    showToast(e.message && e.message !== 'Error en el servidor' ? e.message : 'Hubo un error al publicar la reseña.');
  } finally {
    btn.disabled = false;
    btn.textContent = 'PUBLICAR RESEÑA';
  }
}

document.addEventListener('DOMContentLoaded', () => {
  initReviews();
});

window.resetView = function() {
  AppState.currentMode = 'stock';
  AppState.currentFilter = 'all';
  AppState.searchQuery = '';
  const searchInput = document.getElementById('search-input');
  if (searchInput) searchInput.value = '';
  
  const btnStock = document.getElementById('btn-stock');
  if (btnStock) {
    btnStock.click();
  } else {
    renderProducts();
  }
};

window.showCategory = function(mode, cat) {
  AppState.currentMode = mode;
  AppState.currentFilter = cat;
  AppState.searchQuery = '';
  const searchInput = document.getElementById('search-input');
  if(searchInput) searchInput.value = '';
  
  // Ensure the right main button is activated
  let btnId = '';
  if (mode === 'stock') btnId = 'btn-stock';
  else if (mode === 'preorder') btnId = 'btn-preorder';
  else if (mode === 'preorder-sports') btnId = 'btn-preorder-sports';
  
  if (btnId) {
    const btn = document.getElementById(btnId);
    if(btn) btn.click();
    
    // But since the button click will reset the filter, we need to override the filter AGAIN after the click
    setTimeout(() => {
      AppState.currentFilter = cat;
      renderProducts();
      document.getElementById('productos')?.scrollIntoView({ behavior: 'smooth' });
    }, 10);
  } else {
    renderProducts();
    document.getElementById('productos')?.scrollIntoView({ behavior: 'smooth' });
  }
};

window.goToTopCategory = function(cat) {
  if (cat === 'LIGA MX') {
    const btnSports = document.getElementById('btn-preorder-sports');
    if (btnSports) btnSports.click();
    setTimeout(() => {
      const pill = document.querySelector('#filters-sports .filter-pill[data-filter="liga_mx"]');
      if (pill) pill.click();
      const target = document.getElementById('modo-compra') || document.getElementById('productos');
      if (target) target.scrollIntoView({ behavior: 'smooth' });
    }, 120);
  } else if (cat === 'ON CLOUD') {
    const btnPreorder = document.getElementById('btn-preorder');
    if (btnPreorder) btnPreorder.click();
    setTimeout(() => {
      const pill = document.querySelector('#filters-preorder .filter-pill[data-filter="ON CLOUD"]');
      if (pill) pill.click();
      const target = document.getElementById('modo-compra') || document.getElementById('productos');
      if (target) target.scrollIntoView({ behavior: 'smooth' });
    }, 120);
  } else if (cat === 'BOSS') {
    const btnPreorder = document.getElementById('btn-preorder');
    if (btnPreorder) btnPreorder.click();
    setTimeout(() => {
      const pill = document.querySelector('#filters-preorder .filter-pill[data-filter="Boss"]');
      if (pill) pill.click();
      const target = document.getElementById('modo-compra') || document.getElementById('productos');
      if (target) target.scrollIntoView({ behavior: 'smooth' });
    }, 120);

  } else if (cat === 'MAYOREO') {
    AppState.currentMode = 'stock';
    AppState.currentFilter = 'mayoreo';
    AppState.searchQuery = '';
    const searchInput = document.getElementById('search-input');
    if (searchInput) searchInput.value = '';

    const btnStock = document.getElementById('btn-stock');
    const btnPreorder = document.getElementById('btn-preorder');
    const btnSports = document.getElementById('btn-preorder-sports');
    if (btnStock) {
      btnStock.style.background = '#000000';
      btnStock.style.color = '#ffffff';
      btnStock.style.border = '2px solid #000000';
    }
    if (btnPreorder) {
      btnPreorder.style.background = '#ffffff';
      btnPreorder.style.color = '#4b5563';
      btnPreorder.style.border = '1.5px solid var(--border-subtle)';
    }
    if (btnSports) {
      btnSports.style.background = '#ffffff';
      btnSports.style.color = '#4b5563';
      btnSports.style.border = '1.5px solid var(--border-subtle)';
    }

    const filtersStock = document.getElementById('filters-stock');
    const filtersPreorder = document.getElementById('filters-preorder');
    const filtersSports = document.getElementById('filters-sports');
    const bannerPreorder = document.getElementById('preorder-banner');
    if (filtersStock) {
      filtersStock.style.display = 'flex';
      document.querySelectorAll('#filters-stock .filter-pill').forEach(b => {
        b.classList.toggle('active', b.dataset.filter === 'mayoreo');
      });
    }
    if (filtersPreorder) filtersPreorder.style.display = 'none';
    if (filtersSports) filtersSports.style.display = 'none';
    if (bannerPreorder) bannerPreorder.style.display = 'none';

    const sectionTag = document.getElementById('section-tag-dynamic');
    const sectionTitle = document.getElementById('section-title-dynamic');
    if (sectionTag) {
      sectionTag.textContent = '🔥 DIRECTO DE FÁBRICA';
      sectionTag.style.color = 'var(--neon-red)';
    }
    if (sectionTitle) sectionTitle.textContent = 'LOTES MAYOREO DESTACADOS';

    renderProducts();

    const target = document.getElementById('modo-compra') || document.getElementById('productos');
    if (target) target.scrollIntoView({ behavior: 'smooth' });
  }
};
